import sys, random
sys.path.insert(0,'.')
from modules.byte_program import *
random.seed(7)
def build(depth):
    if depth==0 or random.random()<0.3:
        return literal(bytes(random.randrange(1,255) for _ in range(random.randrange(0,12))))
    k=random.randrange(3)
    if k==0:
        return concat(build(depth-1),build(depth-1))
    if k==1:
        return repeat(build(depth-1), random.randrange(0,4))
    n=build(depth-1)
    if n.length==0: return n
    lo=random.randrange(0,n.length); hi=random.randrange(lo,n.length)
    return cut(n,lo,hi)
bad=0
for trial in range(3000):
    n=build(4)
    data=read(n,0,n.length)
    assert data== (materialize(n,n.length) if n.length<=65536 else data)
    for _ in range(6):
        if n.length==0: continue
        lo=random.randrange(0,n.length); hi=random.randrange(lo,n.length)
        want=int.from_bytes(data[lo:hi],'big')
        # reference: sum (b+1)*257^(len-1-i)
        seg=data[lo:hi]; m=len(seg)
        ref=sum((x+1)*257**(m-1-i) for i,x in enumerate(seg))%(2**64)
        got=hash_range(n,lo,hi)
        if got!=ref:
            bad+=1; print('MISMATCH',trial,lo,hi,n.length); break
print('bad',bad)
"
